import{_ as e,c as r,o as h,ah as i}from"./chunks/framework.Dnh4IO1K.js";const b=JSON.parse('{"title":"困","description":"周易集解 - 困","frontmatter":{"title":"困","description":"周易集解 - 困"},"headers":[],"relativePath":"classics/jijie/047.md","filePath":"classics/jijie/047.md"}'),l={name:"classics/jijie/047.md"};function p(n,a,d,t,s,c){return h(),r("div",null,[...a[0]||(a[0]=[i('<h1 id="困" tabindex="-1">困 <a class="header-anchor" href="#困" aria-label="Permalink to “困”">​</a></h1><h2 id="困-1" tabindex="-1">困 <a class="header-anchor" href="#困-1" aria-label="Permalink to “困”">​</a></h2><h2 id="卦辭" tabindex="-1">卦辭 <a class="header-anchor" href="#卦辭" aria-label="Permalink to “卦辭”">​</a></h2><p>困，亨，貞大人吉，無咎。有言不信。</p><h2 id="卦辭注" tabindex="-1">卦辭注 <a class="header-anchor" href="#卦辭注" aria-label="Permalink to “卦辭注”">​</a></h2><p>《序卦》曰：升而不已必困，故受之以困。</p><p>崔憬曰：冥升在上以消，不富則窮，故言升而不已必困也。</p><p>鄭玄曰：坎為月。互體離，離為日。兌為闇昧，日所入也。今上掩日月之明，猶君子處亂代，為小人所不容，故謂之困也。君子雖困，居險能悅，是以通而無咎也。</p><p>虞翻曰：否二之上，乾坤交，故通也。</p><p>虞翻曰：貞大人吉，謂五也。在困無應，宜靜則無咎。故貞大人吉無咎。</p><p>虞翻曰：震為言，折入兌，故｢有言不信，尚口乃窮｣。</p><h2 id="彖" tabindex="-1">彖 <a class="header-anchor" href="#彖" aria-label="Permalink to “彖”">​</a></h2><p>《彖》曰：困，剛揜也。險以說，困而不失其所亨，其唯君子乎？貞大人吉，以剛中也。有言不信，尚口乃窮也。</p><h2 id="彖傳注" tabindex="-1">彖傳注 <a class="header-anchor" href="#彖傳注" aria-label="Permalink to “彖傳注”">​</a></h2><p>荀爽曰：謂二五為陰所揜也。</p><p>荀爽曰：此本否卦。陽降為險，陰升為悅也。</p><p>荀爽曰：謂二雖揜陰陷險，猶不失中，與正陰合，故通也。喻君子雖陷險中，不失中和之行也。</p><p>荀爽曰：謂五雖揜於陰，近無所據，遠無所應，體剛得中正，居五位，則吉無咎也。</p><p>虞翻曰：兌為口，上變口滅，故尚口乃窮。</p><p>荀爽曰：陰從二升上六，成兌。為有言。失中為不信。動而乘陽，故曰尚口乃窮也。</p><h2 id="象" tabindex="-1">象 <a class="header-anchor" href="#象" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：澤無水，困。君子以致命遂志。</p><h2 id="象傳注" tabindex="-1">象傳注 <a class="header-anchor" href="#象傳注" aria-label="Permalink to “象傳注”">​</a></h2><p>王弼曰：澤無水，則水在澤下也。水在澤下，困之象也。處困而屈其志者，小人也。君子固窮，道可忘乎？</p><p>虞翻曰：君子謂三，伏陽也。否坤為致，巽為命，坎為志，三入陰中，故致命遂志也。</p><h2 id="初六" tabindex="-1">初六 <a class="header-anchor" href="#初六" aria-label="Permalink to “初六”">​</a></h2><p>初六，臀困於株木。入於幽谷，三歲不覿。</p><h2 id="初六注" tabindex="-1">初六注 <a class="header-anchor" href="#初六注" aria-label="Permalink to “初六注”">​</a></h2><p>《九家易》曰：臀謂四。株木，三也。三體為木。澤中無水，兌金傷木，故枯為株也。初者四應，欲進之四，四困於三，故曰｢臀困於株木｣。</p><p>乾寶曰：兌為孔穴，坎為隱伏。隱伏在下，而漏孔穴，臀之象也。</p><p>《九家易》曰：幽谷，二也。此本否卦。謂陽來入坎，與初同體，故曰入幽谷。三者陽數。謂陽陷險中，為陰揜，終不得見。故曰三歲不覿也。</p><h2 id="象-1" tabindex="-1">象 <a class="header-anchor" href="#象-1" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：入於幽谷，幽不明也。</p><h2 id="象傳注-1" tabindex="-1">象傳注 <a class="header-anchor" href="#象傳注-1" aria-label="Permalink to “象傳注”">​</a></h2><p>荀爽曰：為陰所揜，故不明。</p><h2 id="九二" tabindex="-1">九二 <a class="header-anchor" href="#九二" aria-label="Permalink to “九二”">​</a></h2><p>九二，困於酒食，朱紱方來，利用亨祀，徵兇。無咎。</p><h2 id="九二注" tabindex="-1">九二注 <a class="header-anchor" href="#九二注" aria-label="Permalink to “九二注”">​</a></h2><p>案：二本陰位，中饋之職。坎為酒食，上為宗廟，今二陰升上，則酒食入廟。故困於酒食也。上九降二，故朱紱方來。朱紱，宗廟之服。乾為大赤，朱紱之象也。</p><p>荀爽曰：二升在廟，五親奉之，故利用享祀。陰動而上，失中乘陽；陽下而陷，為陰所掩，故曰徵兇。陽降來二，雖位不正，得中有實；陰雖去中，上得居正，而皆免咎，故曰無咎也。</p><h2 id="象-2" tabindex="-1">象 <a class="header-anchor" href="#象-2" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：困於酒食，中有慶也。</p><h2 id="象傳注-2" tabindex="-1">象傳注 <a class="header-anchor" href="#象傳注-2" aria-label="Permalink to “象傳注”">​</a></h2><p>翟玄曰：陽從上來，居中得位，富有二陰，故中有慶也。</p><h2 id="六三" tabindex="-1">六三 <a class="header-anchor" href="#六三" aria-label="Permalink to “六三”">​</a></h2><p>六三，困於石，據於蒺藜，入於其宮，不見其妻，兇。</p><h2 id="六三注" tabindex="-1">六三注 <a class="header-anchor" href="#六三注" aria-label="Permalink to “六三注”">​</a></h2><p>虞翻曰：二變正時，三在艮山下，故困於石。蒺藜，木名。坎為蒺藜。二變艮手，據坎。故據蒺藜者也。</p><p>虞翻曰：巽為入。二動艮為宮，兌為妻，謂上無應也。三在陰下，離象毀壞，隱在坤中，死期將至，故｢不見其妻，兇｣也。</p><h2 id="象-3" tabindex="-1">象 <a class="header-anchor" href="#象-3" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：據於蒺藜，乘剛也。入於其宮，不見其妻，不祥也。</p><h2 id="象傳注-3" tabindex="-1">象傳注 <a class="header-anchor" href="#象傳注-3" aria-label="Permalink to “象傳注”">​</a></h2><p>案：三居坎上，坎為藂棘而木多心，蒺藜之象。</p><p>《九家易》曰：此本否卦，二四同功為艮。艮為門闕，宮之象也。六三居困，而位不正，上困於民，內無仁恩，親戚叛逆，誅將加身。入宮無妻，非常之困，故曰不祥也。</p><h2 id="九四" tabindex="-1">九四 <a class="header-anchor" href="#九四" aria-label="Permalink to “九四”">​</a></h2><p>九四，來徐徐，困於金車，吝，有終。</p><h2 id="九四注" tabindex="-1">九四注 <a class="header-anchor" href="#九四注" aria-label="Permalink to “九四注”">​</a></h2><p>虞翻曰：來欲之初。徐徐，舒遲也。見險，故來徐徐。否乾為金，乾為車。之應歷險，故困於金車。易位得正，故吝有終矣。</p><h2 id="象-4" tabindex="-1">象 <a class="header-anchor" href="#象-4" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：來徐徐，志在下也。雖不當位，有與也。</p><h2 id="象傳注-4" tabindex="-1">象傳注 <a class="header-anchor" href="#象傳注-4" aria-label="Permalink to “象傳注”">​</a></h2><p>王弼曰：下謂初。</p><p>崔憬曰：位雖不當，故吝也。有與於援，故有終也。</p><h2 id="九五" tabindex="-1">九五 <a class="header-anchor" href="#九五" aria-label="Permalink to “九五”">​</a></h2><p>九五，劓刖，困於赤紱，乃徐有說，利用祭祀。</p><h2 id="九五注" tabindex="-1">九五注 <a class="header-anchor" href="#九五注" aria-label="Permalink to “九五注”">​</a></h2><p>虞翻曰：割鼻曰劓。斷足曰刖。四動時震為足，艮為鼻。離為兵，兌為刑。故劓刖也。赤紱謂二。否乾為朱，故赤。坤為紱，二未變應五，故困於赤紱也。</p><p>虞翻曰：兌為說，坤為徐，二動應已，故乃徐有說也。</p><p>崔憬曰：劓刖，刑之小者也。於困之時，不崇柔德，以剛遇剛，雖行其小刑，而失其大柄，故言劓刖也。赤紱，天子祭服之飾。所以稱困者，被奪其政，唯得祭祀。若《春秋傳》曰：政由甯氏，祭則寡人。故曰困於赤紱。居中以直，在困思通。初雖蹔窮，終則必喜，故曰乃徐有說。所以險而能說，窮而能通者，在困於赤紱乎！故曰利用祭祀也。</p><p>案：五應在二，二互體離。離為文明，赤紱之象也。</p><h2 id="象-5" tabindex="-1">象 <a class="header-anchor" href="#象-5" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：劓刖，志未得也。乃徐有說，以中直也。利用祭祀，受福也。</p><h2 id="象傳注-5" tabindex="-1">象傳注 <a class="header-anchor" href="#象傳注-5" aria-label="Permalink to “象傳注”">​</a></h2><p>陸績曰：無據無應，故志未得也。二言朱紱，此言赤紱。二言享祀，此言祭祀。傳互言耳，無他義也。謂二困五，三困四，五初困上，斯乃迭困之義也。</p><p>崔憬曰：以其居中，當位，故有悅。</p><p>荀爽曰：謂五爻合同，據國當位，而主祭祀，故受福也。</p><h2 id="上六" tabindex="-1">上六 <a class="header-anchor" href="#上六" aria-label="Permalink to “上六”">​</a></h2><p>上六，困於葛藟，於臲卼，曰動悔有悔，徵吉。</p><h2 id="上六注" tabindex="-1">上六注 <a class="header-anchor" href="#上六注" aria-label="Permalink to “上六注”">​</a></h2><p>虞翻曰：巽為草莽，稱葛藟，謂三也。兌為刑人。故｢困於葛藟，於臲卼｣也。</p><p>虞翻曰：乘陽，故動悔。變而失正，故有悔。三已變正，已得應之，故徵吉也。</p><h2 id="象-6" tabindex="-1">象 <a class="header-anchor" href="#象-6" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：困於葛藟，未當也。動悔有悔，吉行也。</p><h2 id="象傳注-6" tabindex="-1">象傳注 <a class="header-anchor" href="#象傳注-6" aria-label="Permalink to “象傳注”">​</a></h2><p>虞翻曰：謂三未變，當位應上故也。</p><p>虞翻曰：行謂三，變乃得當位之應，故吉行者也。</p>',86)])])}const m=e(l,[["render",p]]);export{b as __pageData,m as default};
